-- ProcureFlow SQLite database export
-- Generated from the current database

BEGIN TRANSACTION;
CREATE TABLE anomaly_records (
	id INTEGER NOT NULL, 
	entity_type VARCHAR(50) NOT NULL, 
	entity_id VARCHAR(60) NOT NULL, 
	issue_type VARCHAR(80) NOT NULL, 
	ground_truth VARCHAR(20) NOT NULL, 
	expected_decision VARCHAR(120) NOT NULL, 
	reason TEXT NOT NULL, 
	detected BOOLEAN NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id)
);
CREATE TABLE approvals (
	id VARCHAR(30) NOT NULL, 
	request_id VARCHAR(30) NOT NULL, 
	approver_name VARCHAR(120) NOT NULL, 
	approver_role VARCHAR(80) NOT NULL, 
	approval_level INTEGER NOT NULL, 
	decision VARCHAR(20) NOT NULL, 
	threshold_amount NUMERIC(14, 2) NOT NULL, 
	comments TEXT, 
	decided_at DATETIME, 
	PRIMARY KEY (id), 
	CHECK (approval_level > 0), 
	CHECK (decision IN ('PENDING','APPROVED','REJECTED','CHANGES_REQUESTED')), 
	FOREIGN KEY(request_id) REFERENCES purchase_requests (id)
);
CREATE TABLE audit_events (
	id INTEGER NOT NULL, 
	entity_type VARCHAR(50) NOT NULL, 
	entity_id VARCHAR(60) NOT NULL, 
	event_type VARCHAR(80) NOT NULL, 
	old_value TEXT, 
	new_value TEXT, 
	reason TEXT, 
	actor VARCHAR(120), 
	occurred_at DATETIME NOT NULL, 
	PRIMARY KEY (id)
);
CREATE TABLE budgets (
	id VARCHAR(30) NOT NULL, 
	department_id VARCHAR(30) NOT NULL, 
	fiscal_year INTEGER NOT NULL, 
	category VARCHAR(80) NOT NULL, 
	allocated_amount NUMERIC(14, 2) NOT NULL, 
	reserved_amount NUMERIC(14, 2) NOT NULL, 
	spent_amount NUMERIC(14, 2) NOT NULL, 
	effective_from DATE NOT NULL, 
	effective_to DATE, 
	status VARCHAR(20) NOT NULL, 
	PRIMARY KEY (id), 
	CHECK (allocated_amount >= 0), 
	CHECK (reserved_amount >= 0), 
	CHECK (spent_amount >= 0), 
	CHECK (status IN ('ACTIVE', 'INACTIVE', 'CLOSED')), 
	FOREIGN KEY(department_id) REFERENCES departments (id)
);
CREATE TABLE deliveries (
	id VARCHAR(60) NOT NULL, 
	po_id VARCHAR(30) NOT NULL, 
	delivery_date DATE NOT NULL, 
	expected_date DATE NOT NULL, 
	item_quantity INTEGER NOT NULL, 
	received_quantity INTEGER NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	notes TEXT, 
	PRIMARY KEY (id), 
	CHECK (item_quantity > 0), 
	CHECK (received_quantity >= 0), 
	CHECK (status IN ('PENDING','PARTIAL','DELIVERED','DELAYED','REJECTED')), 
	FOREIGN KEY(po_id) REFERENCES purchase_orders (id)
);
CREATE TABLE departments (
	id VARCHAR(30) NOT NULL, 
	name VARCHAR(100) NOT NULL, 
	code VARCHAR(20) NOT NULL, 
	manager_name VARCHAR(120), 
	is_active BOOLEAN NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (name), 
	UNIQUE (code)
);
CREATE TABLE purchase_order_lines (
	id VARCHAR(40) NOT NULL, 
	po_id VARCHAR(30) NOT NULL, 
	quote_line_id VARCHAR(40) NOT NULL, 
	item_name VARCHAR(150) NOT NULL, 
	quantity INTEGER NOT NULL, 
	unit_price NUMERIC(14, 2) NOT NULL, 
	line_total NUMERIC(14, 2) NOT NULL, 
	PRIMARY KEY (id), 
	CHECK (quantity > 0), 
	CHECK (unit_price >= 0), 
	CHECK (line_total >= 0), 
	FOREIGN KEY(po_id) REFERENCES purchase_orders (id), 
	FOREIGN KEY(quote_line_id) REFERENCES supplier_quote_lines (id)
);
CREATE TABLE purchase_orders (
	id VARCHAR(30) NOT NULL, 
	request_id VARCHAR(30) NOT NULL, 
	quote_id VARCHAR(60) NOT NULL, 
	supplier_id VARCHAR(30) NOT NULL, 
	po_date DATE NOT NULL, 
	currency VARCHAR(3) NOT NULL, 
	subtotal NUMERIC(14, 2) NOT NULL, 
	tax_amount NUMERIC(14, 2) NOT NULL, 
	shipping_cost NUMERIC(14, 2) NOT NULL, 
	total_amount NUMERIC(14, 2) NOT NULL, 
	status VARCHAR(30) NOT NULL, 
	award_rationale TEXT, 
	issued_without_approval BOOLEAN NOT NULL, 
	PRIMARY KEY (id), 
	CHECK (total_amount >= 0), 
	CHECK (status IN ('DRAFT','ISSUED','ACKNOWLEDGED','PARTIALLY_DELIVERED','DELIVERED','CANCELLED')), 
	FOREIGN KEY(request_id) REFERENCES purchase_requests (id), 
	FOREIGN KEY(quote_id) REFERENCES supplier_quotes (id), 
	FOREIGN KEY(supplier_id) REFERENCES suppliers (id)
);
CREATE TABLE purchase_requests (
	id VARCHAR(30) NOT NULL, 
	requester_id VARCHAR(30) NOT NULL, 
	department_id VARCHAR(30) NOT NULL, 
	budget_id VARCHAR(30) NOT NULL, 
	request_date DATE NOT NULL, 
	required_date DATE NOT NULL, 
	category VARCHAR(80) NOT NULL, 
	estimated_cost NUMERIC(14, 2) NOT NULL, 
	currency VARCHAR(3) NOT NULL, 
	purpose TEXT NOT NULL, 
	status VARCHAR(30) NOT NULL, 
	duplicate_of_id VARCHAR(30), 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	CHECK (estimated_cost > 0), 
	CHECK (status IN ('DRAFT','SUBMITTED','PENDING_APPROVAL','APPROVED','REJECTED','RFQ_CREATED','ORDERED','PARTIALLY_DELIVERED','COMPLETED','CANCELLED')), 
	FOREIGN KEY(requester_id) REFERENCES requesters (id), 
	FOREIGN KEY(department_id) REFERENCES departments (id), 
	FOREIGN KEY(budget_id) REFERENCES budgets (id), 
	FOREIGN KEY(duplicate_of_id) REFERENCES purchase_requests (id)
);
CREATE TABLE request_lines (
	id VARCHAR(30) NOT NULL, 
	request_id VARCHAR(30) NOT NULL, 
	item_name VARCHAR(150) NOT NULL, 
	description TEXT, 
	category VARCHAR(80) NOT NULL, 
	quantity INTEGER NOT NULL, 
	unit VARCHAR(30) NOT NULL, 
	estimated_unit_price NUMERIC(14, 2) NOT NULL, 
	estimated_total NUMERIC(14, 2) NOT NULL, 
	PRIMARY KEY (id), 
	CHECK (quantity > 0), 
	CHECK (estimated_unit_price >= 0), 
	CHECK (estimated_total >= 0), 
	FOREIGN KEY(request_id) REFERENCES purchase_requests (id)
);
CREATE TABLE requesters (
	id VARCHAR(30) NOT NULL, 
	employee_code VARCHAR(30) NOT NULL, 
	name VARCHAR(120) NOT NULL, 
	email VARCHAR(150) NOT NULL, 
	department_id VARCHAR(30) NOT NULL, 
	job_title VARCHAR(100), 
	is_active BOOLEAN NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (employee_code), 
	UNIQUE (email), 
	FOREIGN KEY(department_id) REFERENCES departments (id)
);
CREATE TABLE rfq_suppliers (
	id INTEGER NOT NULL, 
	rfq_id VARCHAR(30) NOT NULL, 
	supplier_id VARCHAR(30) NOT NULL, 
	invited_at DATETIME, 
	response_status VARCHAR(20) NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (rfq_id, supplier_id), 
	FOREIGN KEY(rfq_id) REFERENCES rfqs (id), 
	FOREIGN KEY(supplier_id) REFERENCES suppliers (id)
);
CREATE TABLE rfqs (
	id VARCHAR(30) NOT NULL, 
	request_id VARCHAR(30) NOT NULL, 
	created_date DATE NOT NULL, 
	closing_date DATE NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	competitive BOOLEAN NOT NULL, 
	exception_reason TEXT, 
	PRIMARY KEY (id), 
	CHECK (status IN ('OPEN','CLOSED','CANCELLED','AWARDED')), 
	FOREIGN KEY(request_id) REFERENCES purchase_requests (id)
);
CREATE TABLE supplier_quote_lines (
	id VARCHAR(40) NOT NULL, 
	quote_id VARCHAR(60) NOT NULL, 
	request_line_id VARCHAR(30) NOT NULL, 
	quantity INTEGER NOT NULL, 
	unit_price NUMERIC(14, 2) NOT NULL, 
	line_total NUMERIC(14, 2) NOT NULL, 
	PRIMARY KEY (id), 
	CHECK (quantity > 0), 
	CHECK (unit_price >= 0), 
	CHECK (line_total >= 0), 
	FOREIGN KEY(quote_id) REFERENCES supplier_quotes (id), 
	FOREIGN KEY(request_line_id) REFERENCES request_lines (id)
);
CREATE TABLE supplier_quotes (
	id VARCHAR(60) NOT NULL, 
	rfq_id VARCHAR(30) NOT NULL, 
	supplier_id VARCHAR(30) NOT NULL, 
	quote_date DATE NOT NULL, 
	valid_until DATE NOT NULL, 
	currency VARCHAR(3) NOT NULL, 
	subtotal NUMERIC(14, 2) NOT NULL, 
	tax_amount NUMERIC(14, 2) NOT NULL, 
	shipping_cost NUMERIC(14, 2) NOT NULL, 
	other_cost NUMERIC(14, 2) NOT NULL, 
	total_landed_cost NUMERIC(14, 2) NOT NULL, 
	delivery_days INTEGER NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	is_awarded BOOLEAN NOT NULL, 
	PRIMARY KEY (id), 
	CHECK (subtotal >= 0), 
	CHECK (tax_amount >= 0), 
	CHECK (shipping_cost >= 0), 
	CHECK (other_cost >= 0), 
	CHECK (total_landed_cost >= 0), 
	CHECK (delivery_days >= 0), 
	CHECK (status IN ('RECEIVED','EXPIRED','REJECTED','AWARDED')), 
	FOREIGN KEY(rfq_id) REFERENCES rfqs (id), 
	FOREIGN KEY(supplier_id) REFERENCES suppliers (id)
);
CREATE TABLE suppliers (
	id VARCHAR(30) NOT NULL, 
	supplier_code VARCHAR(30) NOT NULL, 
	name VARCHAR(150) NOT NULL, 
	email VARCHAR(150) NOT NULL, 
	phone VARCHAR(30), 
	address TEXT, 
	country VARCHAR(80), 
	currency VARCHAR(3) NOT NULL, 
	risk_level VARCHAR(20) NOT NULL, 
	risk_score INTEGER NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	CHECK (risk_score >= 0 AND risk_score <= 100), 
	CHECK (risk_level IN ('LOW','MEDIUM','HIGH')), 
	UNIQUE (supplier_code), 
	UNIQUE (email)
);
